import { useEffect, useState } from 'react';

import { AgentSessionView } from '@/components/agent';
import { StandardDrawer } from '@/components/standard/drawer';
import { StandardPagination } from '@/components/standard/pagination';
import { Button } from '@/components/ui/button';
import type { AgentRunStatus, SessionSummary } from '@/types/dto';

import type { AgentHistorySource, AgentRunHistoryState } from '../hooks/use-agent-run-history';

export interface AgentRunHistoryProps {
  /** workspace root（重放会话取数 / 订阅寻址） */
  root: string | null;
  state: AgentRunHistoryState;
  /** 来源筛选当前值（状态由页面持有） */
  source: AgentHistorySource;
  onSourceChange: (source: AgentHistorySource) => void;
}

/** 来源筛选三态选项（值 + 文案）。 */
const SOURCE_OPTIONS: Array<{ value: AgentHistorySource; label: string }> = [
  { value: 'debug', label: '调试' },
  { value: 'change', label: '变更' },
  { value: 'all', label: '全部' },
];

/** 来源筛选三态按钮组（aria-pressed 高亮当前项；状态由页面持有）。 */
function SourceFilter({
  source,
  onChange,
}: {
  source: AgentHistorySource;
  onChange: (source: AgentHistorySource) => void;
}): React.JSX.Element {
  return (
    <div className="flex items-center gap-1.5" data-testid="history-source-filter">
      {SOURCE_OPTIONS.map((option) => (
        <Button
          key={option.value}
          aria-pressed={source === option.value}
          className={source === option.value ? undefined : 'bg-muted text-muted-foreground'}
          data-source={option.value}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </Button>
      ))}
    </div>
  );
}

/** 状态文案（受控字符串直出） */
function statusLabel(status: AgentRunStatus): string {
  if (status === 'running') return '运行中';
  if (status === 'completed') return '已完成';
  if (status === 'stopped') return '已停止';
  return '失败';
}

/** 会话终态：最新轮行状态（无轮行的空会话按运行中呈灰） */
function sessionStatus(session: SessionSummary): AgentRunStatus | null {
  const last = session.turns.at(-1);
  return last?.status ?? null;
}

/** 单条会话行：更新时间 / 轮数 / 终态，点开重放全史转录 */
function SessionRow({
  session,
  onOpen,
}: {
  session: SessionSummary;
  onOpen: (sessionId: string) => void;
}) {
  const status = sessionStatus(session);
  return (
    <button
      type="button"
      className="block w-full cursor-pointer border-0 border-b border-b-border bg-transparent px-0 py-2 text-left last:border-b-0 hover:text-primary"
      data-testid="agent-run-row"
      data-session-id={session.row.id}
      data-status={status ?? 'empty'}
      onClick={() => onOpen(session.row.id)}
    >
      <span className="mb-0.5 flex items-center gap-2 text-xs">
        <span
          className={
            status === null
              ? 'text-muted-foreground'
              : status === 'failed'
                ? 'text-fail'
                : status === 'completed'
                  ? 'text-pass'
                  : 'text-muted-foreground'
          }
          data-testid="run-status"
        >
          {status === null ? '空会话' : statusLabel(status)}
        </span>
        <span className="text-muted-foreground">{session.stats.turnCount} 轮</span>
        <span className="text-muted-foreground">
          {new Date(session.row.updatedAt).toLocaleString()}
        </span>
      </span>
      <span className="block truncate text-sm text-muted-foreground">{session.row.id}</span>
      {session.turns.at(-1)?.error != null && (
        <span className="block break-all text-xs text-fail" data-testid="run-row-error">
          {session.turns.at(-1)?.error}
        </span>
      )}
    </button>
  );
}

/** 重放区：点开会话的全史转录（只读形态自持建流，限高内部滚动，不撑高页面）。 */
function ReplayArea({
  root,
  sessionId,
  onClose,
}: {
  root: string | null;
  sessionId: string | null;
  onClose?: () => void;
}): React.JSX.Element {
  const [open, setOpen] = useState(sessionId !== null);
  useEffect(() => {
    setOpen(sessionId !== null);
  }, [sessionId]);
  return (
    <StandardDrawer
      title="重放会话"
      data-testid="replay-area"
      content={
        <AgentSessionView root={root} sessionId={sessionId} data-testid="replay-area-session" />
      }
      open={open}
      onOpenChange={(value) => {
        if (open !== value) {
          setOpen(value);
        }
        if (!value) {
          onClose?.();
        }
      }}
    ></StandardDrawer>
  );
}

/**
 * 历史会话区
 */
export function AgentRunHistory({
  root,
  state,
  source,
  onSourceChange,
}: AgentRunHistoryProps): React.JSX.Element {
  return (
    <section
      className="rounded-lg border border-border bg-card px-4 py-3.5"
      data-testid="agent-run-history"
    >
      <div className="mb-2 flex items-center justify-between">
        <h2 className="m-0 text-[15px]">
          历史会话 <span className="text-muted-foreground">({state.total})</span>
        </h2>
        <div className="flex items-center gap-2">
          <SourceFilter source={source} onChange={onSourceChange} />
          <Button disabled={state.loading} data-testid="history-refresh" onClick={state.refresh}>
            刷新历史
          </Button>
        </div>
      </div>
      {state.error !== null && (
        <div
          className="mb-3 break-all rounded-md bg-fail-bg px-3 py-2 text-fail"
          data-testid="history-error"
        >
          历史加载失败：{state.error}
        </div>
      )}
      {state.loading && (
        <div className="text-muted-foreground" data-testid="history-loading">
          加载中…
        </div>
      )}
      {!state.loading && state.total === 0 && state.error === null && (
        <div className="text-muted-foreground" data-testid="history-empty">
          暂无历史会话，点击「刷新历史」获取。
        </div>
      )}
      {state.sessions.map((session) => (
        <SessionRow key={session.row.id} session={session} onOpen={state.openSession} />
      ))}
      {state.totalPages > 1 && (
        <StandardPagination
          page={state.page}
          totalPages={state.totalPages}
          total={state.total}
          disabled={state.loading}
          data-testid="agent-history-pagination"
          onPageChange={state.setPage}
        />
      )}
      <ReplayArea root={root} sessionId={state.selectedSessionId} onClose={state.closeSession} />
    </section>
  );
}

