    ).toBe(true);
    expect(
      note !== null &&
        panel !== null &&
        (note.compareDocumentPosition(panel) & Node.DOCUMENT_POSITION_FOLLOWING) !== 0,
    ).toBe(true);

    // 1s 重试成功（应答携活面步表）→ 横幅出销 + 图面更新到最新轮
    loadActiveRun(
      activeRunView({
        nodes: [
          {
            phase: 'implement',
