describe('TauriAgentTransport：会话参数校验穷尽面', () => {
  it('permissionMode 三值（default / acceptEdits / bypassPermissions）原样透传，transport 不改写', async () => {
    invokeMock.mockResolvedValue(recordRow(13, 'running'));
